{'role': 'user', 'content': [{'tool_use_id': 'toolu_01L2suEx8b6ULxaZ9qCzdMRT', 'type': 'tool_result', 'content': '     1→/**
     2→ * Singleton initializer for the Artifact Engine.
     3→ *
     4→ * Ensures the ArtifactIndex is created and started only once per server
     5→ * process. Wires index events to the EventBus so SSE clients receive
     6→ * real-time updates.
     7→ *
     8→ * All API routes that need artifact data should import `getArtifactIndex()`
     9→ * from this module rather than constructing their own ArtifactIndex.
    10→ */
    11→
    12→import { ArtifactIndex } from "./index";
    13→import { eventBus } from "./event-bus";
    14→import { getSettings } from "@/lib/settings";
    15→
    16→let instance: ArtifactIndex | null = null;
    17→let currentProjectPath: string | null = null;
    18→
    19→/**
    20→ * Returns the running ArtifactIndex singleton.
    21→ * Starts (or restarts) the engine if the project path has changed.
    22→ * Returns null if no project path is configured.
    23→ */
    24→export async function getArtifactIndex(): Promise<ArtifactIndex | null> {
    25→  const settings = getSettings();
    26→  const projectPath = settings.projectPath;
    27→
    28→  if (!projectPath) {
    29→    return null;
    30→  }
    31→
    32→  // Restart if project path changed
    33→  if (instance && currentProjectPath !== projectPath) {
    34→    await instance.stop();
    35→    instance = null;
    36→    currentProjectPath = null;
    37→  }
    38→
    39→  if (!instance) {
    40→    const idx = new ArtifactIndex(projectPath);
    41→
    42→    // Wire index events to the EventBus
    43→    idx.on("change", (record) => {
    44→      eventBus.emitArtifactChanged(record);
    45→    });
    46→    idx.on("remove", (relativePath) => {
    47→      eventBus.emitArtifactRemoved(relativePath);
    48→    });
    49→    idx.on("error", (...args: unknown[]) => {
    50→      // Surface watcher errors (e.g. project folder deleted while running)
    51→      const err = args[0];
    52→      const errMsg = err instanceof Error ? err.message : String(err);
    53→      const message =
    54→        errMsg.toLowerCase().includes("enoent") ||
    55→        errMsg.toLowerCase().includes("no such file")
    56→          ? "Project folder not found. Please re-attach your project."
    57→          : `Watcher error: ${errMsg}`;
    58→      eventBus.emitProjectError(message);
    59→    });
    60→
    61→    await idx.start();
    62→    instance = idx;
    63→    currentProjectPath = projectPath;
    64→  }
    65→
    66→  return instance;
    67→}
    68→
    69→/**
    70→ * Returns the ArtifactIndex synchronously without starting it.
    71→ * Used in contexts where async is not available. Returns null if not yet
    72→ * initialized.
    73→ */
    74→export function getArtifactIndexSync(): ArtifactIndex | null {
    75→  return instance;
    76→}
    77→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01WQmRQBGi85edz9j325P4x9', 'type': 'tool_result', 'content': '     1→/**
     2→ * EventBus bridges ArtifactIndex events to SSE client connections.
     3→ *
     4→ * The singleton EventBus subscribes to the global ArtifactIndex and
     5→ * fans out SSEEvent payloads to all connected HTTP clients.
     6→ *
     7→ * Usage:
     8→ *   eventBus.subscribe(controller);   // in GET /api/events
     9→ *   eventBus.unsubscribe(controller); // on client disconnect
    10→ */
    11→
    12→import type { SSEEvent, ArtifactRecord } from "@/types/index";
    13→
    14→type SendFn = (event: SSEEvent) => void;
    15→
    16→class EventBus {
    17→  private subscribers: Set<SendFn> = new Set();
    18→
    19→  /** Register a new SSE client send function. */
    20→  subscribe(send: SendFn): void {
    21→    this.subscribers.add(send);
    22→  }
    23→
    24→  /** Remove an SSE client (call on disconnect). */
    25→  unsubscribe(send: SendFn): void {
    26→    this.subscribers.delete(send);
    27→  }
    28→
    29→  /** Broadcast an event to all connected clients. */
    30→  broadcast(event: SSEEvent): void {
    31→    for (const send of Array.from(this.subscribers)) {
    32→      try {
    33→        send(event);
    34→      } catch {
    35→        // Client likely disconnected; will be cleaned up on next request
    36→        this.subscribers.delete(send);
    37→      }
    38→    }
    39→  }
    40→
    41→  /** Convenience: broadcast artifact-changed */
    42→  emitArtifactChanged(record: ArtifactRecord): void {
    43→    this.broadcast({ type: "artifact-changed", data: record });
    44→  }
    45→
    46→  /** Convenience: broadcast artifact-removed */
    47→  emitArtifactRemoved(relativePath: string): void {
    48→    this.broadcast({ type: "artifact-removed", data: { path: relativePath } });
    49→  }
    50→
    51→  /** Convenience: broadcast a project-level error (e.g. folder deleted) */
    52→  emitProjectError(message: string): void {
    53→    this.broadcast({ type: "project-error", data: { message } });
    54→  }
    55→}
    56→
    57→// Singleton — shared across all API route invocations in the same server process
    58→export const eventBus = new EventBus();
    59→'}]}

