{'role': 'user', 'content': [{'tool_use_id': 'toolu_01MHa3mcfkQ4v7V8R6c3DJVq', 'type': 'tool_result', 'content': '     1→/**
     2→ * GET /api/events
     3→ *
     4→ * Server-Sent Events endpoint. Streams real-time artifact and status
     5→ * updates to connected frontend clients.
     6→ *
     7→ * Events: connected, artifact-changed, artifact-removed, status-update
     8→ */
     9→
    10→import { NextRequest } from "next/server";
    11→import { eventBus } from "@/lib/artifact-engine/event-bus";
    12→import { getArtifactIndex } from "@/lib/artifact-engine/singleton";
    13→import { getSettings } from "@/lib/settings";
    14→import type { SSEEvent } from "@/types/index";
    15→
    16→export const dynamic = "force-dynamic";
    17→export const runtime = "nodejs";
    18→
    19→function formatSSE(event: SSEEvent): string {
    20→  return `data: ${JSON.stringify(event)}\n\n`;
    21→}
    22→
    23→export async function GET(_req: NextRequest): Promise<Response> {
    24→  // Ensure the artifact engine is running
    25→  await getArtifactIndex();
    26→
    27→  const settings = getSettings();
    28→  const projectPath = settings.projectPath ?? "";
    29→
    30→  // Capture send outside the ReadableStream init so the cancel hook can reference it
    31→  let send: ((event: SSEEvent) => void) | null = null;
    32→
    33→  const stream = new ReadableStream({
    34→    start(controller) {
    35→      const encoder = new TextEncoder();
    36→
    37→      send = function sendEvent(event: SSEEvent): void {
    38→        try {
    39→          controller.enqueue(encoder.encode(formatSSE(event)));
    40→        } catch {
    41→          // Controller closed — clean up
    42→          if (send) {
    43→            eventBus.unsubscribe(send);
    44→            send = null;
    45→          }
    46→        }
    47→      };
    48→
    49→      // Register with the event bus
    50→      eventBus.subscribe(send);
    51→
    52→      // Send the initial connected event
    53→      send({ type: "connected", data: { projectPath } });
    54→    },
    55→
    56→    cancel() {
    57→      // Called by the Web Streams API when the client disconnects
    58→      if (send) {
    59→        eventBus.unsubscribe(send);
    60→        send = null;
    61→      }
    62→    },
    63→  });
    64→
    65→  return new Response(stream, {
    66→    headers: {
    67→      "Content-Type": "text/event-stream",
    68→      "Cache-Control": "no-cache, no-transform",
    69→      Connection: "keep-alive",
    70→      "X-Accel-Buffering": "no",
    71→    },
    72→  });
    73→}
    74→'}]}

