{'role': 'user', 'content': [{'tool_use_id': 'toolu_01B9uZX55VE2DBPiRFWrQ453', 'type': 'tool_result', 'content': '     1→/**
     2→ * In-memory artifact index.
     3→ *
     4→ * Maintains a Map<relativePath, ArtifactRecord> that stays in sync with the
     5→ * filesystem via the file watcher. On startup it does a full directory scan
     6→ * to populate the index, then watches for incremental changes.
     7→ *
     8→ * Exposes change events for the SSE layer to subscribe to.
     9→ *
    10→ * Usage:
    11→ *   const index = new ArtifactIndex("/path/to/project");
    12→ *   await index.start();
    13→ *   index.on("change", (record) => { ... });
    14→ *   index.on("remove", (path) => { ... });
    15→ */
    16→
    17→import { EventEmitter } from "events";
    18→import fs from "fs";
    19→import path from "path";
    20→import { startWatcher } from "./watcher";
    21→import { parseArtifact } from "./parser";
    22→import type { ArtifactRecord, ArtifactType } from "@/types/index";
    23→
    24→export interface ArtifactIndexEvents {
    25→  /** Fired when an artifact is added or updated in the index */
    26→  change: (record: ArtifactRecord) => void;
    27→  /** Fired when an artifact is removed from the index */
    28→  remove: (relativePath: string) => void;
    29→  /** Fired when the initial scan is complete and the watcher is ready */
    30→  ready: () => void;
    31→}
    32→
    33→export class ArtifactIndex extends EventEmitter {
    34→  private projectPath: string;
    35→  private records: Map<string, ArtifactRecord> = new Map();
    36→  private watcherClose: (() => Promise<void>) | null = null;
    37→
    38→  constructor(projectPath: string) {
    39→    super();
    40→    this.projectPath = projectPath;
    41→  }
    42→
    43→  // -------------------------------------------------------------------------
    44→  // Lifecycle
    45→  // -------------------------------------------------------------------------
    46→
    47→  /**
    48→   * Perform an initial directory scan, then attach the file watcher.
    49→   * Resolves when the watcher has fired its "ready" event.
    50→   */
    51→  start(): Promise<void> {
    52→    return new Promise((resolve) => {
    53→      // Full initial scan
    54→      this.scanDirectory(this.projectPath);
    55→
    56→      const watcher = startWatcher(this.projectPath);
    57→      this.watcherClose = watcher.close.bind(watcher);
    58→
    59→      watcher.on("add", (record) => {
    60→        this.upsert(record);
    61→      });
    62→
    63→      watcher.on("change", (record) => {
    64→        this.upsert(record);
    65→      });
    66→
    67→      watcher.on("unlink", (relativePath) => {
    68→        this.remove(relativePath);
    69→      });
    70→
    71→      watcher.on("ready", () => {
    72→        this.emit("ready");
    73→        resolve();
    74→      });
    75→
    76→      watcher.on("error", (err) => {
    77→        this.emit("error", err);
    78→      });
    79→    });
    80→  }
    81→
    82→  /** Stop the watcher and clear the index. */
    83→  async stop(): Promise<void> {
    84→    if (this.watcherClose) {
    85→      await this.watcherClose();
    86→      this.watcherClose = null;
    87→    }
    88→    this.records.clear();
    89→  }
    90→
    91→  // -------------------------------------------------------------------------
    92→  // Query API
    93→  // -------------------------------------------------------------------------
    94→
    95→  /** Returns all indexed artifact records. */
    96→  getAll(): ArtifactRecord[] {
    97→    return Array.from(this.records.values());
    98→  }
    99→
   100→  /** Returns all artifacts of a given type. */
   101→  getByType(type: ArtifactType): ArtifactRecord[] {
   102→    return this.getAll().filter((r) => r.type === type);
   103→  }
   104→
   105→  /**
   106→   * Returns the artifact at the given path, or null.
   107→   * Accepts either a relative path (relative to project root) or an absolute path.
   108→   */
   109→  getByPath(filePath: string): ArtifactRecord | null {
   110→    // Normalise to relative
   111→    const relative = path.isAbsolute(filePath)
   112→      ? path.relative(this.projectPath, filePath)
   113→      : filePath;
   114→    return this.records.get(relative) ?? null;
   115→  }
   116→
   117→  // -------------------------------------------------------------------------
   118→  // Internal helpers
   119→  // -------------------------------------------------------------------------
   120→
   121→  private upsert(record: ArtifactRecord): void {
   122→    this.records.set(record.path, record);
   123→    this.emit("change", record);
   124→  }
   125→
   126→  private remove(relativePath: string): void {
   127→    this.records.delete(relativePath);
