    68→      listenersRef.current.delete(fn);
    69→    };
    70→  }, []);
    71→
    72→  const dispatch = useCallback((event: SSEEvent) => {
    73→    listenersRef.current.forEach((fn) => fn(event));
    74→  }, []);
    75→
    76→  const connect = useCallback(() => {
