    38→/**
    39→ * Start a chokidar watcher on the given project directory.
    40→ *
    41→ * @param projectPath  Absolute path to watch
    42→ * @returns  An EventEmitter with typed add/change/unlink events + a close() method
    43→ */
    44→export function startWatcher(projectPath: string): ArtifactWatcher {
    45→  const emitter = new EventEmitter() as ArtifactWatcher;
    46→
    47→  // Debounce map: absolutePath -> timer
    48→  const pending = new Map<string, ReturnType<typeof setTimeout>>();
    49→
    50→  function scheduleEmit(event: "add" | "change", filePath: string): void {
    51→    const existing = pending.get(filePath);
    52→    if (existing) clearTimeout(existing);
    53→
    54→    const timer = setTimeout(() => {
    55→      pending.delete(filePath);
    56→      try {
    57→        const record = parseArtifact(filePath, projectPath);
    58→        emitter.emit(event, record);
    59→      } catch {
    60→        // parseArtifact should never throw, but guard defensively
    61→      }
    62→    }, DEBOUNCE_MS);
    63→
    64→    pending.set(filePath, timer);
    65→  }
    66→
    67→  const watcher = chokidar.watch(projectPath, {
    68→    ignored: [
    69→      /(^|[/\\])\.[^./]/, // hidden files/dirs (like .git)
    70→      /node_modules/,
    71→      /\.tinyshop/,
    72→    ],
    73→    persistent: true,
    74→    ignoreInitial: false,
    75→    depth: undefined,
    76→    // Only watch .md files
    77→    // chokidar doesn't support glob directly in watch path for v4; we filter in handlers
    78→  });
    79→
    80→  watcher.on("add", (filePath: string) => {
    81→    if (!filePath.endsWith(".md")) return;
    82→    scheduleEmit("add", filePath);
    83→  });
    84→
    85→  watcher.on("change", (filePath: string) => {
    86→    if (!filePath.endsWith(".md")) return;
    87→    scheduleEmit("change", filePath);
    88→  });
    89→
    90→  watcher.on("unlink", (filePath: string) => {
    91→    if (!filePath.endsWith(".md")) return;
    92→    // Cancel any pending debounced emit for this file
    93→    const existing = pending.get(filePath);
    94→    if (existing) {
    95→      clearTimeout(existing);
    96→      pending.delete(filePath);
    97→    }
    98→    const relativePath = path.relative(projectPath, filePath);
    99→    emitter.emit("unlink", relativePath);
   100→  });
   101→
   102→  watcher.on("error", (err: unknown) => {
   103→    emitter.emit("error", err instanceof Error ? err : new Error(String(err)));
   104→  });
   105→
   106→  watcher.on("ready", () => {
   107→    emitter.emit("ready");
   108→  });
   109→
   110→  // Attach close method to the emitter
   111→  (emitter as ArtifactWatcher).close = async () => {
   112→    // Clear all pending debounce timers
   113→    for (const timer of Array.from(pending.values())) {
   114→      clearTimeout(timer);
   115→    }
   116→    pending.clear();
   117→    await watcher.close();
   118→  };
   119→
   120→  return emitter;
   121→}
